'use strict';
// The ONE source of platform constants for the shim.
//
// Everything here is reported by the engine, read from the headers it was actually
// compiled against (spike/quickjs/patches/txiki-node-constants.patch, generated by
// scripts/gen-node-constants.mjs). The shim does not guess, and there is no
// fallback table — a fallback is just a guess with a longer shelf life.
//
// This replaced three hand-written tables, and the reason is not theoretical. The
// fs one was `_isDarwin ? {darwin} : {linux}`, so every non-darwin non-Linux target
// got Linux's values: measured 2026-08-21 against real node on the NetBSD guest,
// 8 of 11 O_* constants were wrong, including O_APPEND (8 vs 1024) and O_NONBLOCK
// (4 vs 2048) — values this shim feeds straight into open() flag translation. It
// had presumably been wrong on every BSD leg for as long as those legs existed,
// and nothing caught it, because a wrong constant does not throw. It just quietly
// opens the file the wrong way.
//
// So: if the engine cannot report its constants, FAIL, loudly and with the
// remedy. A stale engine is exactly the case that used to be papered over.
const REQUIRED_ABI = 1;

const c = globalThis.__tjs_constants;
if (!c || typeof c !== 'object') {
  throw new Error(
    'node-shim: this engine does not report __tjs_constants, so the shim has no '
    + 'trustworthy source for fs/os constants. It predates '
    + 'txiki-node-constants.patch. Rebuild the engine (node scripts/build-tjs.mjs), '
    + 'or point CLODE_TARGET_TEMPLATE at one built from current sources. '
    + 'Refusing to guess: the tables this replaced were measurably wrong on the BSD legs.');
}
if (!(c.abi >= REQUIRED_ABI)) {
  throw new Error(
    `node-shim: engine constants ABI ${c.abi} is older than the required `
    + `${REQUIRED_ABI}. Rebuild the engine from current sources.`);
}

module.exports = {
  REQUIRED_ABI,
  fs: c.fs,
  signals: c.signals,
  errno: c.errno,
  dlopen: c.dlopen,
  priority: c.priority,
  UV_UDP_REUSEADDR: c.UV_UDP_REUSEADDR,
};
